mapper.delete:

DELETE FROM knowledge_vectors kv USING knowledge_documents kd
WHERE kv.document_id = kd.id AND kd.id = #{documentId}
  AND kd.scope = #{userScope} AND kd.user_id = #{userId}

mapper.select:
SELECT kv.id, kv.document_id AS documentId, kv.chunk_index AS chunkIndex, kv.content, jsonb_build_object('documentTitle', kd.title, 'source', CASE WHEN kd.scope = #{userScope} AND kd.user_id IS NOT NULL AND kd.type = 1 AND kd.file_status = 1 THEN '/knowledge-document/' || kd.id || '/download' ELSE NULL END) AS metadata, kd.metadata->>'docCategory' AS docCategory, (1 - (kv.embedding <=> CAST(#{queryEmbedding} AS vector))) AS score FROM knowledge_vectors kv JOIN knowledge_documents kd ON kd.id = kv.document_id WHERE kd.file_status = 1 AND kd.embedding_status = 3 AND kd.scope = #{scope} AND ((#{scope} = #{userScope} AND kd.user_id = #{userId}) OR (#{scope} IN (#{systemScope}, #{learningPathScope}) AND kd.user_id IS NULL)) AND kv.document_id IN
#{did}
ORDER BY kv.embedding <=> CAST(#{queryEmbedding} AS vector) LIMIT #{limit}
